import { useTheme } from "@theme";
import { forwardRef, useState, useEffect, useRef } from "react";
import { clsx } from "clsx";

import { AccordionProps, SECTION_DEFAULT_OPEN } from "./accordion.types";
import { AccordionContext } from "./hooks/use-accordion";
import { AccordionClasses, StyledAccordion } from "./accordion.styles";
import { AccordionSection } from "./subcomponents/accordion-section";
import { AccordionHeader } from "./subcomponents/accordion-header";
import { AccordionContent } from "./subcomponents/accordion-content";
import { AccordionIndicator } from "./subcomponents/accordion-indicator";
import { AccordionTitle } from "./subcomponents/accordion-title";

const AccordionRoot = forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      className,
      variant = "default",
      size = "default",
      children,
      onePanelAtATime = false,
      sectionsInitiallyOpen = SECTION_DEFAULT_OPEN.NONE,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(
      AccordionClasses.root,
      className,
      size === "sm" ? AccordionClasses.sm : undefined,
    );

    const indexRef = useRef<number>(0);
    const [openIndex, setOpenIndex] = useState<number[] | null>(null);
    const initiallyOpenSections = useRef<number[]>([]);

    const registerSection = (isInitialOpen: boolean) => {
      const assignedIndex = indexRef.current++;
      if (isInitialOpen) initiallyOpenSections.current.push(assignedIndex);
      return assignedIndex;
    };

    useEffect(() => {
      let initialIndexes: number[] | null = null;
      if (indexRef.current > 0) {
        if (sectionsInitiallyOpen === SECTION_DEFAULT_OPEN.FIRST) {
          initialIndexes = [0];
        } else if (sectionsInitiallyOpen === SECTION_DEFAULT_OPEN.ALL) {
          initialIndexes = Array.from({ length: indexRef.current }, (_, i) => i);
        } else if (sectionsInitiallyOpen === SECTION_DEFAULT_OPEN.DETERMINED) {
          initialIndexes = [...initiallyOpenSections.current];
        }
      }

      if (onePanelAtATime && initialIndexes && initialIndexes.length > 1) {
        initialIndexes = [initialIndexes[0]];
      }

      setOpenIndex(initialIndexes);
    }, [sectionsInitiallyOpen, onePanelAtATime]);

    return (
      <AccordionContext.Provider
        value={{
          openIndex,
          setOpenIndex,
          onePanelAtATime,
          registerSection,
          sectionsInitiallyOpen,
        }}
      >
        <StyledAccordion
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          variant={variant}
          {...props}
        >
          {children}
        </StyledAccordion>
      </AccordionContext.Provider>
    );
  },
);

AccordionRoot.displayName = "Accordion";

const Accordion = Object.assign(AccordionRoot, {
  Section: AccordionSection,
  Header: AccordionHeader,
  Content: AccordionContent,
  Indicator: AccordionIndicator,
  Title: AccordionTitle,
});

export default Accordion;
